'use client'

import * as React from 'react'
import { Toggle as TogglePrimitive } from 'radix-ui'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'

/**
 * Toggle, 1:1 with the uiKit `Toggle` set (852:21771): a button that stays pressed. Two
 * variants, outline (bg/popover, border/default, radius-lg) and ghost (no fill, radius-md),
 * two sizes, md 32 (14/21) and sm 28 (13/18), 10px side padding, a 16px icon 8px from the
 * label, and a square icon-only form.
 *
 * At rest the label and icon are text/muted. Hover: bg/muted (outline adds border/strong).
 * Focus: an action/primary border, plus the 2px focus ring on outline. Pressed:
 * action/secondary/bg-pressed (outline with border/strong), text/default; pressed + focus
 * adds the ring on both. Disabled: text/subtle, outline on bg/muted. Ghost rounds to radius-lg
 * whenever it is hovered, focused or pressed, as in Figma.
 *
 * States use satin-hover / satin-focus (or data-force), pressed is Radix's data-state="on".
 */
const toggleVariants = cva(
  [
    'sa:inline-flex sa:shrink-0 sa:items-center sa:justify-center sa:gap-2 sa:border sa:font-medium sa:whitespace-nowrap sa:select-none sa:text-text-muted',
    'sa:transition-[background-color,border-color,color,box-shadow,border-radius] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
    'sa:focus-visible:outline-none sa:disabled:pointer-events-none sa:disabled:text-text-subtle',
    'sa:satin-hover:text-text-default sa:satin-focus:text-text-default sa:data-[state=on]:text-text-default',
    // Figma icons are 1.25px at 16; on Iconoir's 24 grid that is 1.875.
    'sa:[&_svg]:pointer-events-none sa:[&_svg]:size-icon-size sa:[&_svg]:shrink-0 sa:[&_svg]:[stroke-width:1.875]',
  ],
  {
    variants: {
      variant: {
        outline: [
          'sa:rounded-lg sa:border-border-default sa:bg-bg-popover',
          'sa:satin-hover:border-border-strong sa:satin-hover:bg-bg-muted',
          'sa:satin-focus:border-action-primary-bg sa:satin-focus:bg-bg-popover sa:satin-focus:[box-shadow:0_0_0_2px_var(--action-focus-ring)]',
          'sa:data-[state=on]:border-border-strong sa:data-[state=on]:bg-action-secondary-bg-pressed',
          'sa:data-[state=on]:satin-hover:border-border-strong sa:data-[state=on]:satin-hover:bg-action-secondary-bg-pressed',
          'sa:data-[state=on]:satin-focus:border-action-primary-bg sa:data-[state=on]:satin-focus:bg-action-secondary-bg-pressed',
          'sa:disabled:border-border-default sa:disabled:bg-bg-muted',
          'sa:disabled:data-[state=on]:border-border-default sa:disabled:data-[state=on]:bg-action-secondary-bg-pressed',
        ],
        ghost: [
          'sa:rounded-md sa:border-transparent sa:bg-transparent',
          'sa:satin-hover:rounded-lg sa:satin-hover:bg-bg-muted',
          // Figma's ghost focus is the primary border alone (its ring is 0px); pressed + focus has the ring.
          'sa:satin-focus:rounded-lg sa:satin-focus:border-action-primary-bg sa:satin-focus:[box-shadow:none]',
          'sa:data-[state=on]:rounded-lg sa:data-[state=on]:bg-action-secondary-bg-pressed',
          'sa:data-[state=on]:satin-hover:bg-action-secondary-bg-pressed',
          'sa:data-[state=on]:satin-focus:[box-shadow:0_0_0_2px_var(--action-focus-ring)]',
          'sa:disabled:rounded-md sa:disabled:data-[state=on]:rounded-md',
        ],
      },
      size: {
        md: 'sa:h-control-height-lg sa:px-2.5 sa:text-base',
        sm: 'sa:h-control-height sa:px-2.5 sa:text-sm sa:leading-[18px]',
      },
      iconOnly: {
        true: 'sa:px-0',
        false: '',
      },
    },
    compoundVariants: [
      { iconOnly: true, size: 'md', className: 'sa:w-control-height-lg' },
      { iconOnly: true, size: 'sm', className: 'sa:w-control-height' },
    ],
    defaultVariants: { variant: 'sa:outline', size: 'md', iconOnly: false },
  },
)

export interface ToggleProps
  extends React.ComponentProps<typeof TogglePrimitive.Root>,
    VariantProps<typeof toggleVariants> {
  /** A 16px icon before the label, or the only content when `iconOnly` (then pass an aria-label). */
  icon?: React.ReactNode
  /** Show a state without interacting, for state sheets. */
  'data-force'?: 'hover' | 'focus'
}

export function Toggle({ className, variant, size, iconOnly, icon, children, ...props }: ToggleProps) {
  return (
    <TogglePrimitive.Root
      data-slot="toggle"
      className={cn(toggleVariants({ variant, size, iconOnly }), className)}
      {...props}
    >
      {icon}
      {!iconOnly && children}
    </TogglePrimitive.Root>
  )
}

export { toggleVariants }
